llm.raw_content:
{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C30"],
      "claim": "Absolute oral bioavailability of morphine, the closest structural analogue (6-hydroxy vs 6-keto), was 21.3% in a cancer patient, directly above the 20% threshold and supporting high F for hydromorphone.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C46"],
      "claim": "Absolute oral bioavailability of morphine immediate-release tablets in healthy volunteers was 32%, supporting high oral F for the closely related hydromorphone scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "Oral bioavailability of morphine-d3 in opioid-dependent patients was 37.2 ± 10.2%, providing additional direct evidence that morphinan opioids with the 3-phenolic hydroxyl and N-methyl group can exceed 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C17"],
      "claim": "Codeine oral bioavailability was estimated at 84 ± 5%, and codeine shares the same morphinan opioid core; this supports high oral F for hydromorphone despite differences in substituents.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C28"],
      "claim": "Nalmefene, another morphinan opioid, has an absolute oral bioavailability of 40–50%, supporting the pattern that morphinan opioids can achieve F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C20"],
      "claim": "Naltrexone oral bioavailability was ~5% due to extensive first-pass metabolism, but naltrexone differs from hydromorphone by N-cyclopropylmethyl and 14-hydroxy substitution, so this low-F evidence transfers weakly and does not overturn the high prediction.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "Hydromorphone is predicted to have high oral bioavailability (F ≥ 20%). The closest analogue morphine shows absolute oral F values mostly 21–52%, and other morphinan opioids such as codeine, nalmefene, and naldemedine also exceed 20%. The low-F naltrexone evidence is less transferable due to structural differences.",
  "evidence_gaps": [
    "No direct hydromorphone oral bioavailability record is present in the evidence set; prediction relies on close analogues.",
    "Oral bioavailability of opioids is variable with formulation, dose, and first-pass metabolism; exact F for hydromorphone is not measured here.",
    "Naltrexone low-bioavailability records are contradictory but structurally less transferable to hydromorphone."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

